package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 12
# cyclomatic_complexity: 2
# max_nesting_depth: 3

# --- HINTS ---
# if/else: branches
# eval: exists
# external_call: Carp::croak
# method_chain: need: $self->build_tree
# method_chain: need: $self->{opt}
# method_chain: need: $self->collapse
# method_chain: need: $tree->[1]
# --- FUNCTION: build_simple_tree ---
sub build_simple_tree {
  my $self = shift;

  my $tree = eval {
    $self->build_tree(@_);
  };
  Carp::croak("$@XML::Simple called") if $@;

  return $self->{opt}->{keeproot}
         ? $self->collapse({}, @$tree)
         : $self->collapse(@{$tree->[1]});
}

