## Specific Function to Test:
package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 91
# cyclomatic_complexity: 20
# max_nesting_depth: 7

# --- HINTS ---
# open: exists
# if/else: branches
# eval: exists
# external_call: XML::NamespaceSupport->new
# external_call: XML::SAX::ParserFactory->parser
# external_call: UNIVERSAL::isa
# external_call: UNIVERSAL::can
# method_chain: var: $sp holds XML::SAX::ParserFactory object
# method_chain: need: $self->handle_options
# method_chain: need: $self->{opt}
# method_chain: need: $self->{nsup}
# method_chain: call: XML::NamespaceSupport->new
# method_chain: need: $self->{ns_prefix}
# method_chain: need: $ref->{$keys[0]}
# method_chain: need: $refsave->{$_}
# method_chain: need: $ref->{$_}
# method_chain: need: $self->{_ancestors}
# method_chain: need: $self->value_to_xml
# method_chain: need: $fh->print
# method_chain: call: XML::SAX::ParserFactory->parser
# method_chain: need: $sp->parse_string
# method_chain: chain: $sp (XML::SAX::ParserFactory) calls parse_string
# --- FUNCTION: XMLout ---
sub XMLout {
  my $self = &_get_object;      # note, @_ is passed implicitly

  croak "XMLout() requires at least one argument" unless(@_);
  my $ref = shift;

  $self->handle_options('out', @_);


  # If namespace expansion is set, XML::NamespaceSupport is required

