## Specific Function to Test:
package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 32
# cyclomatic_complexity: 9
# max_nesting_depth: 7

# --- HINTS ---
# if/else: branches
# method_chain: need: $element->{Name}
# method_chain: need: $self->{opt}
# method_chain: need: $element->{LocalName}
# method_chain: need: $element->{NamespaceURI}
# method_chain: need: $element->{Attributes}
# method_chain: need: $attr->{LocalName}
# method_chain: need: $attr->{NamespaceURI}
# method_chain: need: $attributes->{$name}
# method_chain: need: $attr->{Value}
# method_chain: need: $attributes->{$attr->{Name}}
# method_chain: need: $attr->{Name}
# method_chain: need: $self->{lists}
# method_chain: need: $self->{curlist}
# --- FUNCTION: start_element ---
sub start_element {
  my $self    = shift;
  my $element = shift;

  my $name = $element->{Name};
  if($self->{opt}->{nsexpand}) {
