# max_nesting_depth: 4

# --- HINTS ---
# if/else: branches
# method_chain: need: $self->{curlist}
# method_chain: need: $self->{lists}
# method_chain: need: $self->{tree}
# method_chain: need: $self->{nocollapse}
# method_chain: need: $self->{opt}
# method_chain: need: $self->collapse
# method_chain: need: $tree->[1]
# --- FUNCTION: end_document ---
sub end_document {
  my $self = shift;

  delete($self->{curlist});
  delete($self->{lists});

  my $tree = $self->{tree};
  delete($self->{tree});


  # Return tree as-is to XMLin()

  return($tree) if($self->{nocollapse});


  # Or collapse it before returning it to SAX parser class

  if($self->{opt}->{keeproot}) {
    $tree = $self->collapse({}, @$tree);
  }
  else {
    $tree = $self->collapse(@{$tree->[1]});
  }

  if($self->{opt}->{datahandler}) {
    return($self->{opt}->{datahandler}->($self, $tree));
  }

  return($tree);
}

